1	// Renders a templated OG banner for every NON-BLOG page (blog posts
2	// have bespoke banners via the blog-banner skill): section eyebrow +
3	// frontmatter title + description on the house backdrop, 1200x630.
4	//
5	//   npm run render:page-og            (all pages)
6	//   npm run render:page-og -- guide/standard.md   (narrow re-run)
7	//
8	// Outputs docs_v2/public/og/<path-with-dashes>.png — COMMITTED
9	// artifacts (the Cloudflare build has no browser), wired to og:image
10	// per page in config.ts transformHead. Re-run locally when a page's
11	// title/description changes.
12	import { mkdirSync, readdirSync, readFileSync, statSync, writeFileSync, rmSync } from 'node:fs';
13	import { resolve, join, dirname } from 'node:path';
14	import { fileURLToPath, pathToFileURL } from 'node:url';
15	import { chromium } from 'playwright';
16	
17	const scriptDirectory = dirname(fileURLToPath(import.meta.url));
18	const docsRoot = resolve(scriptDirectory, '..');
19	const outputDirectory = resolve(docsRoot, 'public/og');
20	mkdirSync(outputDirectory, { recursive: true });
21	
22	const fontsDirectory = resolve(
23	  docsRoot,
24	  '../.claude/skills/blog-banner/banners/fonts',
25	);
26	const lockupPath = resolve(docsRoot, 'public/brand-lockup-dark.png');
27	
28	const EYEBROWS = {
29	  guide: 'GUIDE',
30	  examples: 'EXAMPLES',
31	  api: 'API REFERENCE',
32	  releases: 'RELEASES',
33	  'community.md': 'COMMUNITY',
34	  'engine.md': 'THE ENGINE',
35	};
36	
37	function* markdownFiles(directory, prefix = '') {
38	  for (const entry of readdirSync(directory)) {
39	    if (entry.startsWith('.') || entry === 'node_modules') continue;
40	    const path = join(directory, entry);
41	    const relative = prefix ? `${prefix}/${entry}` : entry;
42	    if (statSync(path).isDirectory()) {
43	      if (['blog', 'public', 'scripts'].includes(relative)) continue;
44	      yield* markdownFiles(path, relative);
45	    } else if (entry.endsWith('.md')) {
46	      // the home page keeps the hand-made site og-image
47	      if (relative === 'index.md' || relative === '404.md') continue;
48	      yield relative;
49	    }
50	  }
51	}
52	
53	function frontmatterField(source, field) {
54	  const frontmatter = source.match(/^---\n[\s\S]*?\n---/)?.[0] ?? '';
55	  const match = frontmatter.match(
56	    new RegExp(`^${field}:\\s*(?:'([^']*)'|"([^"]*)"|(.+))$`, 'm'),
57	  );
58	  return match ? (match[1] ?? match[2] ?? match[3] ?? '').trim() : '';
59	}
60	
61	function escapeHtml(text) {
62	  return text
63	    .replaceAll('&', '&amp;')
64	    .replaceAll('<', '&lt;')
65	    .replaceAll('>', '&gt;');
66	}
67	
68	function bannerHtml(eyebrow, title, description) {
69	  const titleSize =
70	    title.length <= 26 ? 62 : title.length <= 44 ? 52 : title.length <= 66 ? 44 : 38;
71	  return `<!doctype html>
72	<html><head><meta charset="utf-8" />
73	<style>
74	  @font-face { font-family: 'Geist'; font-style: normal; font-weight: 300 800;
75	    src: url(${pathToFileURL(join(fontsDirectory, 'geist-latin.woff2'))}) format('woff2'); }
76	  @font-face { font-family: 'Geist Mono'; font-style: normal; font-weight: 400 600;
77	    src: url(${pathToFileURL(join(fontsDirectory, 'geist-mono-latin.woff2'))}) format('woff2'); }
78	  * { margin: 0; padding: 0; box-sizing: border-box; }
79	  html, body { width: 1200px; height: 630px; overflow: hidden; }
80	  body {
81	    background:
82	      radial-gradient(1000px 560px at 50% -20%, rgba(99, 102, 241, 0.25), transparent 60%),
83	      radial-gradient(900px 560px at 50% 130%, rgba(34, 211, 238, 0.14), transparent 55%),
84	      #050a18;
85	    font-family: 'Geist', 'DejaVu Sans', 'Inter', sans-serif;
86	    position: relative;
87	  }
88	  .grid {
89	    position: absolute; inset: 0;
90	    background-image:
91	      linear-gradient(rgba(59, 130, 246, 0.06) 1px, transparent 1px),
92	      linear-gradient(90deg, rgba(59, 130, 246, 0.06) 1px, transparent 1px);
93	    background-size: 48px 48px;
94	    mask-image: radial-gradient(760px 480px at 50% 50%, black 25%, transparent 75%);
95	    -webkit-mask-image: radial-gradient(760px 480px at 50% 50%, black 25%, transparent 75%);
96	  }
97	  .stage {
98	    position: absolute; inset: 0;
99	    display: flex; flex-direction: column;
100	    align-items: center; justify-content: center;
101	    gap: 24px; padding: 64px 90px 44px;
102	    text-align: center;
103	  }
104	  .eyebrow {
105	    font-family: 'Geist Mono', 'DejaVu Sans Mono', monospace;
106	    font-size: 17px; letter-spacing: 0.22em;
107	    padding: 8px 20px; border-radius: 999px;
108	    border: 1px solid rgba(96, 165, 250, 0.4); color: #7e9cd0;
109	  }
110	  .title {
111	    font-size: ${titleSize}px; font-weight: 750; color: #eaf2ff;
112	    text-shadow: 0 0 44px rgba(59, 130, 246, 0.5); letter-spacing: -0.015em;
113	    line-height: 1.14;
114	    max-width: 1020px;
115	  }
116	  .description {
117	    font-size: 24px; color: #7e9cd0; line-height: 1.55; max-width: 940px;
118	    display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical;
119	    overflow: hidden;
120	  }
121	  .beam {
122	    width: 240px; height: 3px; border-radius: 999px; margin-top: 4px;
123	    background: linear-gradient(90deg, #6366f1, #2dd4bf 60%, #34d399);
124	    box-shadow: 0 0 22px rgba(45, 212, 191, 0.6);
125	  }
126	  .lockup { position: absolute; top: 34px; left: 44px; }
127	  .lockup img { display: block; width: 178px; }
128	  .site {
129	    position: absolute; bottom: 30px; right: 44px;
130	    font-family: 'Geist Mono', 'DejaVu Sans Mono', monospace;
131	    font-size: 15px; color: #52688f;
132	  }
133	</style></head>
134	<body>
135	  <div class="grid"></div>
136	  <div class="lockup"><img src="${pathToFileURL(lockupPath)}" alt="" /></div>
137	  <div class="stage">
138	    <div class="eyebrow">${escapeHtml(eyebrow)}</div>
139	    <div class="title">${escapeHtml(title)}</div>
140	    ${description ? `<div class="beam"></div><div class="description">${escapeHtml(description)}</div>` : '<div class="beam"></div>'}
141	  </div>
142	  <div class="site">ivue.dev</div>
143	</body></html>`;
144	}
145	
146	const requested = process.argv.slice(2).filter((arg) => !arg.startsWith('-'));
147	const pages = [...markdownFiles(docsRoot)].filter(
148	  (page) => !requested.length || requested.includes(page),
149	);
150	
151	const browser = await chromium.launch();
152	const page = await browser.newPage({
153	  viewport: { width: 1200, height: 630 },
154	  deviceScaleFactor: 1,
155	});
156	let rendered = 0;
157	for (const relative of pages) {
158	  const source = readFileSync(resolve(docsRoot, relative), 'utf8');
159	  const title =
160	    frontmatterField(source, 'title') ||
161	    source.match(/^# (.+)$/m)?.[1]?.replace(/[`*]/g, '') ||
162	    relative;
163	  const description = frontmatterField(source, 'description');
164	  const section = relative.includes('/') ? relative.split('/')[0] : relative;
165	  const eyebrow = EYEBROWS[section] ?? 'IVUE';
166	  const outputName =
167	    relative.replace(/\.md$/, '').replaceAll('/', '-') + '.png';
168	
169	  // a real file:// document, not setContent — about:blank documents
170	  // cannot load file:// fonts
171	  const scratchPath = resolve(outputDirectory, '.render.html');
172	  writeFileSync(scratchPath, bannerHtml(eyebrow, title, description));
173	  await page.goto(pathToFileURL(scratchPath).href, { waitUntil: 'networkidle' });
174	  await page.evaluate(() => document.fonts.ready);
175	  await page.screenshot({ path: resolve(outputDirectory, outputName) });
176	  rendered += 1;
177	}
178	await browser.close();
179	rmSync(resolve(outputDirectory, '.render.html'), { force: true });
180	console.log(`page og: ${rendered} banners → docs_v2/public/og/`);
181

