8	 *
9	 * Get-only static accessors whose name starts with `$` become
10	 * compute-once-per-receiver caches: the getter body runs on first read
11	 * through a given class, its result is stored under a symbol OWN property
12	 * of that receiver, and later reads return the stored value. The
13	 * `Object.hasOwn` guard never walks the prototype chain, so a parent's
14	 * cache can never shadow a subclass — each class in a hierarchy derives
15	 * through its own overrides on its own first read, in ANY read order.
16	 * The `$` prefix IS the API: it promises STABLE IDENTITY per receiver,
17	 * nothing more — whether the cached value is then treated as immutable
18	 * config or as a mutable memo table is the author's design. A static
19	 * getter that must stay live (a knob for subclasses to pinch, a
20	 * fresh-per-read value) must not use the prefix.
21	 *
22	 * Method binding uses the same per-receiver symbol discipline: the bound
23	 * function is cached under a symbol own property, never under the method
24	 * name — so a parent-first read can never install a parent-bound method
25	 * where a subclass's chain lookup would find it.
26	 *
27	 * `$` semantics are GRANTED BY the transform: a raw class, a raw
28	 * subclass, or a class only passed through `Reactive()` keeps native
29	 * getter behavior. A class that needs instance reactivity AND static
30	 * `$`-caches composes the transforms: `Static(Reactive($Class))`.
31	 *
32	 * This is the namespace pattern's backend adapter: canonical namespace +
33	 * mutable `Class` slot + late reads, for STATELESS capability classes (a
34	 * function bag). Never wrap stateful/reactive instance classes with it — use
35	 * `Reactive()` for those; `Static()` operates on the single class object and
36	 * has no instance dimension.
37	 *
38	 * Ships from `ivue/extras` (not the reactive core) so the primary `ivue`
39	 * entry stays minimal.
40	 */
41	export type ClassConstructor = new (...arguments_: any[]) => any;
42	
43	const hasOwn = Object.hasOwn;
44	
45	export function Static<Class extends ClassConstructor>(targetClass: Class): Class {
46	  const SelectedClass = class extends targetClass {};
47	  const visitedKeys = new Set<PropertyKey>();
48	
49	  for (
50	    let currentClass: ClassConstructor = targetClass;
51	    currentClass !== Function.prototype;
52	    currentClass = Object.getPrototypeOf(currentClass)
53	  ) {
54	    for (const key of Reflect.ownKeys(currentClass)) {
55	      if (visitedKeys.has(key)) continue;
56	      visitedKeys.add(key);
57	
58	      const descriptor = Object.getOwnPropertyDescriptor(currentClass, key)!;
59	
60	      if (typeof descriptor.value === 'function') {
61	        const method = descriptor.value;
62	        const bindKey =
63	          typeof key === 'string'
64	            ? Symbol.for(`ivue.staticBound.${key}`)
65	            : Symbol('ivue.staticBound');
66	
67	        Object.defineProperty(SelectedClass, key, {
68	          configurable: true,
69	          enumerable: descriptor.enumerable,
70	          get(this: any) {
71	            if (!hasOwn(this, bindKey)) {
72	              Object.defineProperty(this, bindKey, {
73	                configurable: true,
74	                value: method.bind(this),
75	              });
76	            }
77	            return this[bindKey];
78	          },
79	        });
80	      } else if (
81	        descriptor.get &&
82	        !descriptor.set &&
83	        typeof key === 'string' &&
84	        key.startsWith('$')
85	      ) {
86	        const getter = descriptor.get;
87	        const cacheKey = Symbol.for(`ivue.staticCache.${key}`);
88	
89	        Object.defineProperty(SelectedClass, key, {
90	          configurable: true,
91	          enumerable: descriptor.enumerable,
92	          get(this: any) {
93	            if (!hasOwn(this, cacheKey)) {
94	              Object.defineProperty(this, cacheKey, {
95	                configurable: true,
96	                value: getter.call(this),
97	              });
98	            }
99	            return this[cacheKey];
100	          },
101	        });
102	      }
103	    }
104	  }
105	
106	  return SelectedClass as Class;
107	}
