1	/**
2	 * `LazyShared<T>` — the safe shared-store cell for static classes.
3	 *
4	 * The static-class split (see `Static()`): `$`-prefixed static getters
5	 * are compute-once-PER-RECEIVER caches — perfect for memos and per-class
6	 * tuning, where a subclass forking its own copy is the feature. A SHARED
7	 * store (a registry, a ledger) must never live there: per-receiver
8	 * caching means a subclass reading `this.$store` silently forks the
9	 * registry. The fix is a `static readonly` FIELD — one reference on the
10	 * declaring class, inherited, never receiver-cached — but an eager field
11	 * initializer runs at MODULE LOAD, so it may only hold dependency-free
12	 * values; the moment it constructs another namespace's class it races
13	 * import cycles.
14	 *
15	 * `LazyShared` closes the triangle. The field eagerly stores the CELL
16	 * (load-safe — a thunk evaluates nothing), the thunk runs on first
17	 * `.value` read (cycle-safe — every module in any import cycle has
18	 * finished loading), and memoization mutates cell-internal state
19	 * (fork-safe — no receiver, subclass included, can fork it):
20	 *
21	 *   class $SearchRegistry {
22	 *     protected static readonly sharedBackend = new LazyShared(
23	 *       () => new SearchBackend.Class(),
24	 *     );
25	 *     protected static get $backend() {
26	 *       return this.sharedBackend.value; // the field IS the pin
27	 *     }
28	 *   }
29	 *
30	 * A thunk that reads its own cell (directly or through another cell)
31	 * throws a NAMED cycle error instead of a bare stack overflow, and a
32	 * failed construction leaves the cell retryable, never poisoned.
33	 *
34	 * Ships from `ivue/extras` (not the reactive core) so the primary `ivue`
35	 * entry stays minimal.
36	 */
37	export class LazyShared<T> {
38	  constructor(private readonly make: () => T) {}
39	
40	  private constructed = false;
41	  private constructing = false;
42	  private stored: T | null = null;
43	
44	  get value(): T {
45	    if (!this.constructed) {
46	      if (this.constructing) {
47	        throw new Error(
48	          'LazyShared thunk cycle: this cell is read inside its own ' +
49	            'construction. Break the dependency between the two thunks.',
50	        );
51	      }
52	      this.constructing = true;
53	      try {
54	        this.stored = this.make();
55	        this.constructed = true;
56	      } finally {
57	        this.constructing = false;
58	      }
59	    }
60	    return this.stored as T;
61	  }
62	
63	  /**
64	   * Drop the constructed value; the next read constructs again. For
65	   * tests and process recomposition — production code never resets.
66	   */
67	  reset(): void {
68	    this.constructed = false;
69	    this.stored = null;
70	  }
71	}
